import { logged } from './dec.ts';
export class Svc {
  // A method decorator cannot go on a field.
  @logged
  name = 'x';
}

// A method decorator — its context is a ClassMethodDecoratorContext.
export function logged<T, A extends unknown[], R>(fn: (this: T, ...args: A) => R, ctx: ClassMethodDecoratorContext): (this: T, ...args: A) => R {
  return function (this: T, ...args: A): R { console.log(String(ctx.name)); return fn.call(this, ...args); };
}

import { logged } from '../src/dec.ts';
class Bad {
  @logged // expect TS1240
  count = 0;
}
export { Bad };

